<?php
namespace App\Services\CRM; use App\Models\{Guest,Promotion}; use Illuminate\Validation\ValidationException;
class PromotionService { public function calculate(Promotion $p,float $amount,?Guest $guest=null):float {if(!$p->is_active||now()->lt($p->starts_at)||now()->gt($p->ends_at))throw ValidationException::withMessages(['promotion'=>'Promotion is not currently valid.']);if($amount<(float)$p->minimum_spend)throw ValidationException::withMessages(['promotion'=>'Minimum spend has not been reached.']);if($p->usage_limit!==null&&$p->used_count>=$p->usage_limit)throw ValidationException::withMessages(['promotion'=>'Promotion usage limit has been reached.']);if($guest&&$p->per_guest_limit!==null&&$p->redemptions()->where('guest_id',$guest->id)->count()>=$p->per_guest_limit)throw ValidationException::withMessages(['promotion'=>'Guest promotion usage limit has been reached.']);$d=$p->type==='fixed'?(float)$p->value:$amount*((float)$p->value/100);if($p->maximum_discount!==null)$d=min($d,(float)$p->maximum_discount);return min($amount,round($d,2));} }
